<script setup lang="ts">
import { ref } from 'vue'
import AppShell from '../components/AppShell.vue'
import { api } from '../api'
import { useAuthStore } from '../stores/auth'
import { Check, KeyRound, ShieldCheck, UserRound } from '@lucide/vue'
import { errorText } from '../utils/format'
const auth=useAuthStore(), oldPassword=ref(''), newPassword=ref(''), confirmPassword=ref(''), busy=ref(false), error=ref(''), success=ref('')
function validate(){if(!oldPassword.value){error.value='请输入当前密码';return false}if(newPassword.value.length<8||newPassword.value.length>128){error.value='新密码长度需为 8–128 位';return false}if(newPassword.value!==confirmPassword.value){error.value='两次输入的新密码不一致';return false}if(oldPassword.value===newPassword.value){error.value='新密码需与当前密码不同';return false}return true}
async function change(){error.value='';success.value='';if(!validate())return;busy.value=true;const g=auth.generation;try{await api.changePassword(oldPassword.value,newPassword.value);if(g===auth.generation){success.value='密码已更新。你的当前登录状态仍然有效。';oldPassword.value='';newPassword.value='';confirmPassword.value=''}}catch(e){if(g===auth.generation)error.value=errorText(e)}finally{if(g===auth.generation)busy.value=false}}
</script>
<template><AppShell><section class="page-heading"><div><span class="eyebrow">个人中心</span><h1>账户设置</h1><p>管理你的校园卡账户资料与安全选项。</p></div></section>
  <div class="settings-layout"><section class="surface-card profile-card"><div class="section-heading"><div><h2>个人资料</h2><p>当前登录账户信息</p></div><span class="profile-shield"><ShieldCheck :size="18"/></span></div><div class="profile-hero"><span class="profile-avatar">{{auth.user?.fullName.slice(0,1)}}</span><span><b>{{auth.user?.fullName}}</b><small>{{auth.user?.role==='ADMIN'?'系统管理员':'学生账户'}}</small></span></div><div class="profile-field"><span>用户名</span><b>{{auth.user?.username}}</b></div><div class="profile-field"><span>学号</span><b>{{auth.user?.studentNo||'—'}}</b></div><div class="profile-field"><span>账户状态</span><b class="status-chip" :class="auth.user?.enabled?'success':'disabled'">{{auth.user?.enabled?'启用中':'已停用'}}</b></div></section>
    <section class="surface-card password-card"><div class="section-heading"><div><h2>修改密码</h2><p>使用强密码保护校园卡账户。</p></div><span class="password-icon"><KeyRound :size="18"/></span></div><form class="password-form" @submit.prevent="change"><label class="field-label" for="old-password">当前密码</label><input id="old-password" v-model="oldPassword" type="password" autocomplete="current-password" :disabled="busy" placeholder="输入当前密码"/><label class="field-label" for="new-password">新密码</label><input id="new-password" v-model="newPassword" type="password" autocomplete="new-password" :disabled="busy" placeholder="8–128 位"/><small class="field-help">建议使用长度至少 8 位的密码。</small><label class="field-label" for="confirm-password">确认新密码</label><input id="confirm-password" v-model="confirmPassword" type="password" autocomplete="new-password" :disabled="busy" placeholder="再次输入新密码"/><div v-if="error" class="form-alert"><span class="alert-dot"></span>{{error}}</div><div v-if="success" class="success-banner"><Check :size="17"/> {{success}}</div><button class="button button-primary password-submit" :disabled="busy||!oldPassword||!newPassword||!confirmPassword"><span v-if="busy" class="spinner spinner-light"></span><KeyRound v-else :size="17"/> {{busy?'正在更新…':'更新密码'}}</button></form></section>
  </div>
</AppShell></template>
